package com.utewedding.app.domain.entity;
import com.utewedding.app.domain.*;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity@Table(name="risk_events")public class RiskEventEntity{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="rule_code",nullable=false,length=60)private String ruleCode;@Column(name="rule_version",nullable=false)private int ruleVersion;@Column(name="subject_type",nullable=false,length=30)private String subjectType;@Column(name="subject_id",nullable=false,length=190)private String subjectId;@Column(nullable=false)private int score;@Column(nullable=false,length=20)private String severity;@Enumerated(EnumType.STRING)@Column(name="recommended_action",nullable=false,length=30)private RiskAction recommendedAction;@Enumerated(EnumType.STRING)@Column(name="effective_action",nullable=false,length=30)private RiskAction effectiveAction;@JdbcTypeCode(SqlTypes.JSON)@Column(nullable=false,columnDefinition="jsonb")private String evidence="{}";@Column(name="deduplication_key",nullable=false,unique=true,length=190)private String deduplicationKey;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private RiskEventStatus status=RiskEventStatus.OPEN;@Column(name="resolution_note",length=1000)private String resolutionNote;@Column(name="resolved_by")private UUID resolvedBy;@Column(name="resolved_at")private Instant resolvedAt;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@PrePersist void create(){if(createdAt==null)createdAt=Instant.now();}public UUID getId(){return id;}public String getRuleCode(){return ruleCode;}public int getRuleVersion(){return ruleVersion;}public String getSubjectType(){return subjectType;}public String getSubjectId(){return subjectId;}public int getScore(){return score;}public String getSeverity(){return severity;}public RiskAction getRecommendedAction(){return recommendedAction;}public RiskAction getEffectiveAction(){return effectiveAction;}public String getEvidence(){return evidence;}public RiskEventStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public void setRuleCode(String v){ruleCode=v;}public void setRuleVersion(int v){ruleVersion=v;}public void setSubjectType(String v){subjectType=v;}public void setSubjectId(String v){subjectId=v;}public void setScore(int v){score=v;}public void setSeverity(String v){severity=v;}public void setRecommendedAction(RiskAction v){recommendedAction=v;}public void setEffectiveAction(RiskAction v){effectiveAction=v;}public void setEvidence(String v){evidence=v;}public void setDeduplicationKey(String v){deduplicationKey=v;}public void resolve(RiskEventStatus s,UUID actor,String note){status=s;resolvedBy=actor;resolutionNote=note;resolvedAt=Instant.now();}}
